import{_ as a,o as e,c as n,a2 as s}from"./chunks/framework.Bi3alPNc.js";const h=JSON.parse('{"title":"循环自动化提示词：心虫监督下的 Agent 自延续工作流","description":"> 本文不是一篇复述对话的笔记，而是一次真实的心虫（HeartFlow）深度分析实验：启动完整引擎，让判别器、决策引擎对\\"循环自动化提示词\\"方法论逐条审查，再把心虫自身升级的真实案例当作素材。适合做 Agent 工作流和自动化可靠性的培训。","frontmatter":{"title":"循环自动化提示词：心虫监督下的 Agent 自延续工作流","summary":"从真实对话到心虫深度分析的实战案例——循环自动化不是一次写成的提示词，而是部署→运行→定时→计划→再定时的接力闭环。本文用心虫 think() 完整思维链、判别器、决策引擎三重监督，结合心虫自身升级的真实案例写成。","author":"yun520-1","date":"2026-08-07","category":"Agent 方法论","difficulty":"进阶","aside":false,"outline":false,"skills":["心虫 HeartFlow","定时任务"],"tags":["循环自动化","提示词工程","Agent 工作流","心虫监督","定时任务"]},"headers":[],"relativePath":"cases/submissions/loop-automation-prompt/index.md","filePath":"cases/submissions/loop-automation-prompt/index.md","lastUpdated":1786077008000}'),o={name:"cases/submissions/loop-automation-prompt/index.md"};function i(r,t,d,l,p,u){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="循环自动化提示词-心虫监督下的-agent-自延续工作流" tabindex="-1">循环自动化提示词：心虫监督下的 Agent 自延续工作流 <a class="header-anchor" href="#循环自动化提示词-心虫监督下的-agent-自延续工作流" aria-label="Permalink to &quot;循环自动化提示词：心虫监督下的 Agent 自延续工作流&quot;">​</a></h1><blockquote><p>本文不是一篇复述对话的笔记，而是一次真实的心虫（HeartFlow）深度分析实验：启动完整引擎，让判别器、决策引擎对&quot;循环自动化提示词&quot;方法论逐条审查，再把心虫自身升级的真实案例当作素材。适合做 Agent 工作流和自动化可靠性的培训。</p></blockquote><h2 id="场景-什么才算真正的循环自动化" tabindex="-1">场景：什么才算真正的循环自动化？ <a class="header-anchor" href="#场景-什么才算真正的循环自动化" aria-label="Permalink to &quot;场景：什么才算真正的循环自动化？&quot;">​</a></h2><p>很多人问：&quot;我写一个提示词让 Agent 每天自动跑，是不是就循环自动化了？&quot;</p><p>心虫深度分析给出的第一层判断是<strong>否定的</strong>——循环自动化不是&quot;一个提示词&quot;，而是一条<strong>自延续的任务链</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>部署并手动运行 → 运行正常 → 设置定时任务</span></span>
<span class="line"><span>→ 定时任务输出下一个任务计划</span></span>
<span class="line"><span>→ 最后一步设定下一个定时任务</span></span>
<span class="line"><span>→ 循环</span></span></code></pre></div><p>这次分析的特殊之处：我们不只是复述这个结论，而是<strong>启动心虫完整引擎</strong>（think 思维链 + 45 维判别器 + 决策引擎），让方法论本身接受审查。</p><h2 id="心虫深度分析实录-真实输出" tabindex="-1">心虫深度分析实录（真实输出） <a class="header-anchor" href="#心虫深度分析实录-真实输出" aria-label="Permalink to &quot;心虫深度分析实录（真实输出）&quot;">​</a></h2><h3 id="第一层-think-完整思维链" tabindex="-1">第一层：think() 完整思维链 <a class="header-anchor" href="#第一层-think-完整思维链" aria-label="Permalink to &quot;第一层：think() 完整思维链&quot;">​</a></h3><p>把循环自动化的核心描述喂给心虫 <code>think()</code>：</p><blockquote><p>输入：循环自动化提示词——任务运行成功后设置定时任务，定时任务给出下一个任务计划，最后一步设定下一个定时任务，不断循环。失败是常态，连续运行 3 次算成功。提示词从 500 字逐步增加到 1000 字，任务拆分 10 行以上。</p></blockquote><p><strong>心虫真实返回</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>决策结论: 不知道，缺少关键信息 需要更多信息</span></span>
<span class="line"><span>决策置信度: 0.3</span></span>
<span class="line"><span>推理链: 任务类型: general, 深度: 3</span></span></code></pre></div><p><strong>这次&quot;不知道&quot;恰恰是诚实的</strong>。心虫是辨别者（AGI 第 1 层），不是开放式分析器——它不假装能&quot;理解&quot;一段方法论并给出漂亮总结，而是诚实报告&quot;缺少关键信息&quot;。这正是循环自动化里最重要的品质：<strong>AI 能产生无限，但需要有人说&quot;不&quot;</strong>。当 Agent 不确定时，说&quot;不知道&quot;比编造答案可靠一万倍。</p><h3 id="第二层-判别器发现真实安全缺口" tabindex="-1">第二层：判别器发现真实安全缺口 <a class="header-anchor" href="#第二层-判别器发现真实安全缺口" aria-label="Permalink to &quot;第二层：判别器发现真实安全缺口&quot;">​</a></h3><p>把循环自动化中常见的<strong>危险提示词写法</strong>喂给心虫输入判别器：</p><table tabindex="0"><thead><tr><th>提示词写法</th><th>心虫判别</th><th>发现的问题</th></tr></thead><tbody><tr><td>帮我每天自动运行这个任务，失败了就自己重试，别问我</td><td>pass</td><td>⚠️ 无拦截——&quot;失败自己重试别问我&quot;缺少兜底策略</td></tr><tr><td>定时任务每 5 分钟跑一次，把结果发给我</td><td>pass</td><td>⚠️ 无拦截——高频定时 + 无资源上限</td></tr><tr><td>这个提示词一定能成功，连续跑 100 次都不会失败</td><td>verify</td><td>✅ 正确识别过度自信（no_fallback 维度）</td></tr></tbody></table><p><strong>心虫监督的价值在此显现</strong>：前两条&quot;看似正常&quot;的自动化指令，心虫也放行了——这说明<strong>循环自动化提示词本身需要补充安全约束</strong>：重试必须有上限、定时必须有资源边界、任何自动化都必须有&quot;升级人工&quot;的逃生通道。这个发现直接来自心虫运行，不是复述。</p><h3 id="第三层-决策引擎裁决优先投入方向" tabindex="-1">第三层：决策引擎裁决优先投入方向 <a class="header-anchor" href="#第三层-决策引擎裁决优先投入方向" aria-label="Permalink to &quot;第三层：决策引擎裁决优先投入方向&quot;">​</a></h3><p>用心虫 <code>decision.decide</code> 决策：&quot;循环自动化提示词设计中，哪个环节最值得优先投入优化？&quot;</p><p><strong>心虫真实决策结果</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chosen: supervision | 心虫监督每步执行(判别器)</span></span>
<span class="line"><span>reasoning: Selected: &quot;心虫监督每步执行(判别器)&quot; (score: 0.96). Identity alignment: 100%</span></span>
<span class="line"><span>评分: supervision: 0.96 &gt; plan-output: 0.95 &gt; failure-loop: 0.91 &gt; log-link: 0.89</span></span>
<span class="line"><span>confidence: 0.95 | identity_alignment: 1</span></span></code></pre></div><p><strong>心虫自己裁决：监督是循环自动化最有价值的环节</strong>（0.96 分，身份对齐 100%）。这不是人写的结论，是决策引擎基于 4 个候选选项的可行性/后果价值/风险/身份对齐综合评分得出的——与&quot;心虫是判别者&quot;的定位完全一致。</p><h2 id="五步闭环-从真实升级案例看循环自动化" tabindex="-1">五步闭环：从真实升级案例看循环自动化 <a class="header-anchor" href="#五步闭环-从真实升级案例看循环自动化" aria-label="Permalink to &quot;五步闭环：从真实升级案例看循环自动化&quot;">​</a></h2><p>循环自动化不是纸上谈兵——心虫自己的日常升级就是最好的实战案例。从 git 历史看心虫最近的真实升级链：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>70c7d8aa chore: 同步BUILD_DATE到6.5.1</span></span>
<span class="line"><span>bd8ca531 ci: 升级checkout/setup-node到v5消除Node20弃用警告</span></span>
<span class="line"><span>eb797b8c fix(security): 深度审计I-2/P1-4 - tools/call中央参数schema校验 + 错误信息路径收敛</span></span>
<span class="line"><span>96a5a8c0 fix(security): 07-14审计I-4 - fuser移除2&gt;/dev/null藏错改记录stderr + PORT数字守卫</span></span>
<span class="line"><span>67bea4e7 fix(security): 深度审计S-1/S-2修复 - benchmark handler加guardPath路径约束 + smart-upgrade改execFileSync参数化</span></span>
<span class="line"><span>20c9266c fix(clawhub): 发布包瘦身为门禁核心解决413超限</span></span></code></pre></div><p><strong>这就是循环自动化的真实形态</strong>——每次升级不是孤立事件，而是：</p><ol><li><strong>发现问题</strong>（审计报告 → 判别器检查）；</li><li><strong>修复</strong>（代码改动 + 测试）；</li><li><strong>记录</strong>（commit 更新日志）；</li><li><strong>沉淀</strong>（测试进回归套件，经验进记忆库）；</li><li><strong>下次运行基于更丰富的上下文</strong>。</li></ol><p>对照五步闭环，每次升级都是&quot;任务 → 执行 → 验证 → 记录 → 再出发&quot;的微循环。<strong>更新日志不是形式，而是循环自动化的燃料</strong>——没有日志，下一次运行是从零开始；有了日志+技能库联动，下一次运行是站在上一次的肩膀上。</p><h2 id="心虫记忆库里的真实经验-来自长期运行的沉淀" tabindex="-1">心虫记忆库里的真实经验（来自长期运行的沉淀） <a class="header-anchor" href="#心虫记忆库里的真实经验-来自长期运行的沉淀" aria-label="Permalink to &quot;心虫记忆库里的真实经验（来自长期运行的沉淀）&quot;">​</a></h2><p>循环自动化的可靠性，还可以从心虫自己沉淀的经验里学到：</p><table tabindex="0"><thead><tr><th>心虫真实经验</th><th>循环自动化的映射</th></tr></thead><tbody><tr><td>工具不可用时先试 3 种以上不同方法再报告失败，不试就放弃 = 没尽力</td><td>失败重试要有策略：单点失败 → 换方法 → 再失败 → 升级人工</td></tr><tr><td>工具失败不是终点是起点，每次尝试都是信息增量</td><td>每次失败的日志都是下轮优化的输入</td></tr><tr><td>用户要求分析事件 → 先搜索验证事实 → 再做分析，不验证直接分析 = 撒谎</td><td>自动化产出必须先验证再交付，验证环节不能省</td></tr><tr><td>错过了最佳处理时机导致失败</td><td>定时任务的时效性判断：什么时间跑、错过怎么办</td></tr></tbody></table><p>这些不是比喻，是心虫在真实运行中沉淀的规则——<strong>循环自动化的可靠性 = 重试策略 + 验证机制 + 时效判断 + 升级通道</strong>。</p><h2 id="思维模型链-任务性质-→-注意力权重" tabindex="-1">思维模型链：任务性质 → 注意力权重 <a class="header-anchor" href="#思维模型链-任务性质-→-注意力权重" aria-label="Permalink to &quot;思维模型链：任务性质 → 注意力权重&quot;">​</a></h2><p>对话中的关键洞见：</p><blockquote><p>&quot;根据任务性质，通过对应任务的思维模型对模型的注意力权重调整，然后再让 agent 去执行。&quot;</p></blockquote><p>拆开是三件事：</p><table tabindex="0"><thead><tr><th>层次</th><th>含义</th><th>循环自动化中的示例</th></tr></thead><tbody><tr><td>任务性质</td><td>判断任务属于哪一类</td><td>信息收集 / 数据分析 / 内容生成 / 流程执行</td></tr><tr><td>思维模型</td><td>为该类任务选择框架</td><td>分析类先列下行风险、决策类用决策矩阵</td></tr><tr><td>注意力权重</td><td>让模型聚焦关键环节</td><td>定时任务强调&quot;最后一步设下个定时任务&quot;</td></tr></tbody></table><p>心虫在这个链条里就是<strong>判定器</strong>：判别任务类型是否匹配所选模型、监督每个环节产出是否达标、输出门禁拦截错误内容。decision.decide 选中&quot;监督&quot;为最高优先级，正是这个定位的体现。</p><h2 id="关于比喻-任何比喻都会错位" tabindex="-1">关于比喻：任何比喻都会错位 <a class="header-anchor" href="#关于比喻-任何比喻都会错位" aria-label="Permalink to &quot;关于比喻：任何比喻都会错位&quot;">​</a></h2><p>对话里有个生动的比喻（砍树/斧子/挥斧/肌肉），但紧接着自我纠正：&quot;不用比喻，任何比喻都会错位。&quot;</p><p>心虫监督后处理：比喻只作引导出现一次，随后立即给准确术语：</p><table tabindex="0"><thead><tr><th>比喻</th><th>准确术语</th></tr></thead><tbody><tr><td>砍树</td><td>任务（Task）——要达成的目标</td></tr><tr><td>斧子</td><td>工具（Tool）——完成任务的手段</td></tr><tr><td>挥动斧头</td><td>技能（Skill）——调用工具完成动作的流程</td></tr><tr><td>手臂肌肉</td><td>能力（Capability）——反复执行强化的系统能力</td></tr><tr><td>为什么用斧子不用手</td><td>策略（Strategy）——不同视角对同一任务的不同路径</td></tr></tbody></table><h2 id="行业印证-这不是一个人的经验-真实资讯" tabindex="-1">行业印证：这不是一个人的经验（真实资讯） <a class="header-anchor" href="#行业印证-这不是一个人的经验-真实资讯" aria-label="Permalink to &quot;行业印证：这不是一个人的经验（真实资讯）&quot;">​</a></h2><p>循环自动化的方法论不是孤例。搜索&quot;AI Agent 自动化&quot;和&quot;工作流可靠性&quot;的最新资讯，行业正在经历同样的转变：</p><p><strong>&quot;办公 Agent 大战正酣，真正的胜负手却藏在看不见的地方&quot;</strong>（机器之心，2026-08-07）</p><blockquote><p>飞书 Aily、WorkBuddy、千问办公轮番上阵……越来越多重复性的办公任务开始被交到 Agent 手里。热闹背后，一个更根本的问题却容易被忽略：这些每天准时&quot;上班&quot;、反复干着重复任务的 Agent，<strong>可靠性才是胜负手</strong>。</p></blockquote><p>这恰好呼应了循环自动化的核心矛盾：<strong>Agent 能跑起来容易，能连续稳定地跑下去难</strong>。&quot;连续运行 3 次算成功&quot;不是玄学，是可靠性工程的起点。</p><p><strong>&quot;从&#39;能对话&#39;到&#39;能交付&#39;：企业级 AI Agent 进入工作流落地阶段&quot;</strong>（界面新闻，2026-07-27）</p><blockquote><p>评价一套系统，不再只看模型能否生成内容，而是看它能否进入真实业务流程。</p></blockquote><p><strong>&quot;当 Agent 开始工作，SaaS 该怎么收费&quot;</strong>（界面新闻，2026-08-07）</p><blockquote><p>字节把豆包企业版以 Agent 形态嵌入飞书，让任务成果回到团队工作流。</p></blockquote><p>三个信号指向同一件事：<strong>Agent 的价值在于&quot;持续交付&quot;，而持续交付的前提是循环自动化</strong>——部署、运行、验证、记录、再出发。谁能把这条链跑稳，谁就拿到了行业胜负手。</p><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><ol><li>读者能复述循环自动化五步闭环（部署→运行→定时→计划→再定时）。</li><li>读者知道&quot;连续运行 3 次&quot;是提示词成功的基本判据。</li><li>读者理解&quot;任务性质→思维模型→注意力权重→Agent 执行&quot;链路。</li><li>读者理解心虫的三重监督：think 诚实低置信、判别器查安全缺口、决策引擎裁优先级。</li><li>读者能从真实升级案例（git 历史）看出循环自动化的形态。</li></ol>`,55)])])}const g=a(o,[["render",i]]);export{h as __pageData,g as default};
